import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { isRecord } from "./is-record.js";
/** Published npm package name. */
export const PACKAGE_NAME = "@grok/agent-sdk";
/** Previous published name. Imports and the `bdk` bin still resolve. */
export const PREVIOUS_PACKAGE_NAME = "@cursor/bdk";
/** Older published name. In-repo agents still import it. */
export const FORMER_PACKAGE_NAME = "@cursor/july";
const RUNTIME_PACKAGE_NAMES = [PACKAGE_NAME, PREVIOUS_PACKAGE_NAME, FORMER_PACKAGE_NAME];
const HOSTED_WORKTREE_SHA_FILENAME = ".cursor-hosted-worktree-sha";
const GIT_COMMIT_SHA_RE = /^[0-9a-f]{40,64}$/;
/**
 * Bracketed product tag for stderr / ServeOptions.logger lines
 * (`[bdk] …`, `[bdk/slack] …`).
 */
export const LOG_PRODUCT = "bdk";
export const LOG_PREFIX = `[${LOG_PRODUCT}]`;
export const SLACK_LOG_PREFIX = `[${LOG_PRODUCT}/slack]`;
/** The bin name, for help text and copy-pasteable hints. */
export const CLI_COMMAND_NAME = "agent-sdk";
/**
 * True when this module runs from compiled `dist/` output (a published
 * install, or `node dist/bin/agent-serve.js`). False when running from
 * TypeScript source under a host loader (`tsx src/bin/agent-serve.ts`),
 * where tsconfig paths already resolve the framework's import names.
 */
export function isCompiledDistribution() {
    const url = import.meta.url;
    return !(url.endsWith(".ts") || url.endsWith(".mts"));
}
/**
 * Package root of the running copy: `src|dist/internal/distribution.*` is
 * always two directories below it.
 */
export function packageRootDir() {
    return fileURLToPath(new URL("../..", import.meta.url));
}
function packageManifest() {
    const parsed = JSON.parse(readFileSync(join(packageRootDir(), "package.json"), "utf8"));
    if (!isRecord(parsed) || typeof parsed.version !== "string" || !isRecord(parsed.exports)) {
        throw new Error("package.json is missing version or exports");
    }
    const exportsMap = {};
    for (const [key, value] of Object.entries(parsed.exports)) {
        if (!isRecord(value))
            continue;
        const entry = {};
        if (typeof value.import === "string")
            entry.import = value.import;
        const source = value["anysphere-source"];
        if (typeof source === "string")
            entry["anysphere-source"] = source;
        if (entry.import === undefined && entry["anysphere-source"] === undefined)
            continue;
        exportsMap[key] = entry;
    }
    return { version: parsed.version, exports: exportsMap };
}
/** Version of the running package (from its own package.json). */
export function packageVersion() {
    return packageManifest().version;
}
/**
 * Git commit of a checkout-built framework distribution. Published npm
 * packages do not carry this marker and return undefined.
 */
export function packageGitSha() {
    try {
        const sha = readFileSync(join(packageRootDir(), "dist", HOSTED_WORKTREE_SHA_FILENAME), "utf8")
            .trim()
            .toLowerCase();
        return GIT_COMMIT_SHA_RE.test(sha) ? sha : undefined;
    }
    catch {
        return undefined;
    }
}
export function cliVersionInfo() {
    return {
        name: PACKAGE_NAME,
        version: packageVersion(),
    };
}
/**
 * Text or JSON for `version` / `--version` / `-V`.
 * Text is the bare `package.json` version (npm-style). `--json` is the
 * complete `{ name, version, cli }` payload.
 */
export function formatCliVersion(options) {
    const info = cliVersionInfo();
    if (options?.json === true) {
        return `${JSON.stringify(info, null, 2)}\n`;
    }
    return `${info.version}\n`;
}
/**
 * `@grok/agent-sdk[/subpath]`, `@cursor/bdk[/subpath]`, and `@cursor/july[/subpath]` → `file:` URL of this
 * copy's `import` target, for every subpath in the package `exports` map.
 * The published manifest points at `dist/`; Bazel's staged copy points at
 * the in-place `src/` emit, and the aliases follow whichever the manifest says.
 */
export function frameworkAliases() {
    const root = packageRootDir();
    const entries = [];
    for (const [exportPath, conditions] of Object.entries(packageManifest().exports)) {
        const file = conditions?.import;
        if (typeof file !== "string" || file.length === 0) {
            continue;
        }
        const href = pathToFileURL(join(root, file)).href;
        const suffix = exportPath === "." ? "" : `/${exportPath.slice(2)}`;
        for (const name of RUNTIME_PACKAGE_NAMES) {
            entries.push([`${name}${suffix}`, href]);
        }
    }
    return Object.fromEntries(entries);
}
/** Exports that ship no import target. The alias hook resolves them from source. */
export function sourceOnlyFrameworkSpecifiers() {
    const specifiers = [];
    for (const [exportPath, conditions] of Object.entries(packageManifest().exports)) {
        const file = conditions?.import;
        if (typeof file === "string" && file.length > 0) {
            continue;
        }
        const source = conditions?.["anysphere-source"];
        if (typeof source !== "string" || source.length === 0) {
            continue;
        }
        const suffix = exportPath === "." ? "" : `/${exportPath.slice(2)}`;
        for (const name of RUNTIME_PACKAGE_NAMES) {
            specifiers.push(`${name}${suffix}`);
        }
    }
    return specifiers;
}
